import Foundation

/// Localizes only text generated by this app, at display time. File names, paths,
/// camera tags, ICC names and unknown metadata values remain verbatim user data.
enum LocalizationMetadata {
    static func value(_ source: String, for key: String) -> String {
        switch key {
        case "类型":
            for label in ["音频", "视频"] where source.hasSuffix(" " + label) {
                return String(source.dropLast(label.count + 1)) + " " + L10n.tr(label)
            }
        case "尺寸":
            if let parts = captures(#"^(\d+) × (\d+) 像素$"#, source), let w = Int(parts[0]), let h = Int(parts[1]) {
                return L10n.format("%d × %d 像素", w, h)
            }
        case "时长":
            if let parts = captures(#"^([0-9]+(?:\.[0-9]+)?) 秒$"#, source), let seconds = Double(parts[0]) {
                return L10n.format("%.1f 秒", seconds)
            }
        case "快门":
            if let parts = captures(#"^([0-9]+(?:\.[0-9]+)?|1/[0-9]+) 秒$"#, source) {
                return L10n.format("%@ 秒", parts[0])
            }
        case "预览":
            if let parts = captures(#"^(\d+) × (\d+) 像素（矢量渲染）$"#, source), let w = Int(parts[0]), let h = Int(parts[1]) {
                return L10n.format("%d × %d 像素（矢量渲染）", w, h)
            }
        case "大图预览":
            if let parts = captures(#"^(\d+) × (\d+) 像素；缩放按原尺寸计算，预览细节有限$"#, source), let w = Int(parts[0]), let h = Int(parts[1]) {
                return L10n.format("%d × %d 像素；缩放按原尺寸计算，预览细节有限", w, h)
            }
        case "页面":
            if let parts = captures(#"^第 (\d+) 页，共 (\d+) 页$"#, source), let current = Int(parts[0]), let total = Int(parts[1]) {
                return L10n.format("第 %d 页，共 %d 页", current, total)
            }
        case "播放方式", "格式": return L10n.tr(source)
        default: return source
        }
        return source
    }
    private static func captures(_ pattern: String, _ source: String) -> [String]? {
        guard let regex = try? NSRegularExpression(pattern: pattern),
              let match = regex.firstMatch(in: source, range: NSRange(source.startIndex..., in: source)) else { return nil }
        return (1..<match.numberOfRanges).map { (source as NSString).substring(with: match.range(at: $0)) }
    }
}
